CREATE TABLE orders (
    order_id INT,
    customer_id INT,
    total_amount NUMERIC(10,2)
);
INSERT INTO orders VALUES (1, 101, 600.00), (2, 101, 150.00), (3, 102, 750.00);

-- Basic CTE computing high-value orders
WITH high_value_orders AS (
    SELECT order_id, customer_id, total_amount
    FROM orders
    WHERE total_amount > 500.00
)
SELECT customer_id, COUNT(*) AS count_high_orders
FROM high_value_orders
GROUP BY customer_id;

CREATE TABLE employees (
    id INT,
    department VARCHAR(50),
    salary INT
);
INSERT INTO employees VALUES (1, 'AI', 90000), (2, 'AI', 100000), (3, 'HR', 60000);

WITH dept_stats AS (
    SELECT department, AVG(salary) AS avg_sal
    FROM employees
    GROUP BY department
),
company_benchmarks AS (
    SELECT AVG(avg_sal) AS benchmark_sal
    FROM dept_stats
)
SELECT d.department, d.avg_sal, b.benchmark_sal
FROM dept_stats d
CROSS JOIN company_benchmarks b
WHERE d.avg_sal > b.benchmark_sal;

CREATE TABLE users (id INT, email VARCHAR(100), is_active BOOLEAN);
CREATE TABLE auth_logs (user_id INT, login_time TIMESTAMP);
INSERT INTO users VALUES (1, 'ana@example.com', TRUE), (2, 'bob@example.com', FALSE);
INSERT INTO auth_logs VALUES (1, '2026-09-24 10:00:00');

-- Clean CTE pattern vs nested subquery
WITH verified_users AS (
    SELECT id, email FROM users WHERE is_active = TRUE
),
recent_logins AS (
    SELECT user_id, MAX(login_time) AS last_login
    FROM auth_logs
    GROUP BY user_id
)
SELECT u.email, l.last_login
FROM verified_users u
INNER JOIN recent_logins l ON u.id = l.user_id;
